    status character varying(30) NOT NULL,
    razorpay_customer_id character varying(255),
    razorpay_payment_id character varying(255),
    razorpay_subscription_id character varying(255) NOT NULL,
    CONSTRAINT saas_subscriptions_pending_plan_check CHECK (((pending_plan)::text = ANY ((ARRAY['MONTHLY'::character varying, 'YEARLY'::character varying, 'BASE'::character varying, 'PRO'::character varying, 'ENTERPRISE'::character varying])::text[]))),
    CONSTRAINT saas_subscriptions_plan_check CHECK (((plan)::text = ANY ((ARRAY['MONTHLY'::character varying, 'YEARLY'::character varying, 'BASE'::character varying, 'PRO'::character varying, 'ENTERPRISE'::character varying])::text[]))),
    CONSTRAINT saas_subscriptions_status_check CHECK (((status)::text = ANY ((ARRAY['CREATED'::character varying, 'AUTHENTICATION_PENDING'::character varying, 'ACTIVE'::character varying, 'PAYMENT_FAILED'::character varying, 'HALTED'::character varying, 'CANCELLED'::character varying, 'COMPLETED'::character varying, 'EXPIRED'::character varying])::text[])))
);

