    CONSTRAINT shops_registration_type_check CHECK (((registration_type)::text = ANY ((ARRAY['REGULAR'::character varying, 'COMPOSITION'::character varying, 'UNREGISTERED'::character varying])::text[]))),
    CONSTRAINT shops_subscription_tier_check CHECK (((subscription_tier)::text = ANY ((ARRAY['TRIAL'::character varying, 'BASE'::character varying, 'PRO'::character varying, 'ENTERPRISE'::character varying])::text[])))
);

